{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reject **20% / AUD 4.8m**. Maintain **25% / AUD 6m**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Replace the **AUD 25,000 de minimis** with **AUD 5,000**"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Require **24 months after Completion**, not 18 months."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject assimilation into the general regime. Require a **separate 100% cap and at least six years**"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve **fraud, wilful concealment and deliberate misconduct** out of all caps, baskets, time limits, exclusive remedies and non-reliance provisions"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject deemed disclosure of the entire data room, public registers and broadly described records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket exclusion covering Buyer, advisers and matters merely discoverable through searches."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require **effective consent and evidence that its conditions are satisfied before Completion**. Reasonable endeavours and delivery alone are insufficient."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Reject an unsecured promise of a post-Completion release."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include **AUD 420,000 plus triggered on-costs** as an express funds-flow line item or ensure Seller funds them."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity beyond the specific SOW3 payment to address the related ownership/transfer defect and resulting exposure"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require **log preservation, investigation, updates and assessment of access, scope and any notification/remediation obligations**."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Review the three renewals together for timing, scope, accrual, cancellation rights and whether commitments are unavoidable."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep Title, Tax, IP, payment and covenant categories distinct, with explicit treatment and no hidden general-regime override."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent title/ownership, encumbrance and authority evidence, alongside appropriate transfer deliverables. The register alone is insufficient."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Reject Seller’s assertion that these positions are settled under the general regime. **They remain open**"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

